from __future__ import annotations
from collections import Counter
from typing import Dict, List, Tuple
State = Tuple[int, int]

def states(c: Dict[int, int]) -> List[State]:
    return [(degree, 1 if value > 0 else -1)
            for degree, value in c.items() for _ in range(abs(value))]

def aggregate(items: List[State]) -> Dict[int, int]:
    out: Counter[int] = Counter()
    for area, sign in items:
        out[area] += sign
    return dict(sorted((k, v) for k, v in out.items() if v))

def product(left: List[State], right: List[State]) -> List[State]:
    return [(a + b, sa * sb) for a, sa in left for b, sb in right]

trefoil = {-1: 1, 0: -1, 1: 1}
product_coefficients = aggregate(product(states(trefoil), states(trefoil)))
assert product_coefficients == {-2: 1, -1: -2, 0: 3, 1: -2, 2: 1}
print(product_coefficients)

