    for north_tuple in combinations(range(2 * n), n):
        north = set(north_tuple)
        path = tuple("N" if i in north else "E" for i in range(2 * n))
        if forbidden(path):
            continue
        east_seen = area = 0
        for step in path:
            if step == "E":
                east_seen += 1
            else:
                area += east_seen
        counts[area] += 1
    return dict(sorted(counts.items()))

from __future__ import annotations
from typing import Dict, List, Mapping, Tuple
State = Tuple[int, int]

def construct_unit_signed_model(coefficients: Mapping[int, int]) -> List[State]:
    model: List[State] = []
    for degree, coefficient in sorted(coefficients.items()):
        sign = (coefficient > 0) - (coefficient < 0)
        model.extend((degree, sign) for _ in range(abs(coefficient)))
    return model

def aggregate(model: List[State]) -> Dict[int, int]:
    result: Dict[int, int] = {}
    for degree, sign in model:
        result[degree] = result.get(degree, 0) + sign
    return {k: v for k, v in sorted(result.items()) if v != 0}

from __future__ import annotations
from collections import Counter
from typing import Dict, Mapping

def sparse_cauchy_product(left: Mapping[int, int], right: Mapping[int, int]) -> Dict[int, int]:
    result: Counter[int] = Counter()
    for i, coefficient_i in left.items():
        for j, coefficient_j in right.items():
            result[i + j] += coefficient_i * coefficient_j
    return {degree: value for degree, value in sorted(result.items()) if value != 0}

